<script>
(function(){
function g(id){return document.getElementById(id)}
function esc(v){if(v==null)return'';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function pct(c,m){c=parseFloat(c);m=parseFloat(m);if(!(m>0))return 0;return Math.max(0,Math.min(100,Math.round(c/m*100)))}

var raw=g('straw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};

function condColor(c){
  c=(c||'').toLowerCase();
  if(c==='pristine')return 'var(--safe)';
  if(c==='worn')return 'var(--caution)';
  if(c==='damaged')return 'var(--concern)';
  if(c==='broken')return 'var(--danger)';
  return 'var(--mu)';
}

/* VITALS */
var hp=d.hp||{cur:0,max:100};var st=d.stamina||{cur:0,max:100};
g('hp-fill').style.width=pct(hp.cur,hp.max)+'%';
g('hp-val').textContent=esc(hp.cur)+' / '+esc(hp.max);
g('st-fill').style.width=pct(st.cur,st.max)+'%';
g('st-val').textContent=esc(st.cur)+' / '+esc(st.max);

/* CONDITIONS */
var condEl=g('conditions-badges');
var conds=d.conditions||[];
if(conds.length){
  condEl.innerHTML=conds.map(function(c){return '<span class="badge">'+esc(c)+'</span>';}).join('');
}else{
  condEl.innerHTML='<span class="badge none">Nothing to report</span>';
}

/* PURSE */
var purse=d.purse||{};
g('v-purse').textContent=(purse.amount!=null?purse.amount:'—')+(purse.currency?' '+purse.currency:'');

/* FINE DETAILS */
var detEl=g('details-list');
var details=d.details||[];
if(details.length){
  detEl.innerHTML=details.map(function(t){return '<div class="detail-row"><span class="detail-mark">✎</span><span>'+esc(t)+'</span></div>';}).join('');
}else{
  detEl.innerHTML='<div class="empty-note">Nothing worth noting, for now.</div>';
}

/* ON PERSON */
var posEl=g('person-list');
var onPerson=d.onPerson||[];
if(onPerson.length){
  posEl.innerHTML=onPerson.map(function(it){
    var col=condColor(it.condition);
    return '<div class="pos-row"><div class="pos-dot"></div><div>'+
      '<span class="pos-nm">'+esc(it.name||'—')+'</span>'+
      (it.condition?'<span class="pos-cond" style="color:'+col+';border-color:'+col+'66;background:'+col+'14">'+esc(it.condition)+'</span>':'')+
      (it.desc?'<div class="pos-desc">'+esc(it.desc)+'</div>':'')+
    '</div></div>';
  }).join('');
}else{
  posEl.innerHTML='<div class="empty-note">Nothing carried on their person.</div>';
}

/* TRUNK — grouped by category, unlimited items */
var trunkEl=g('trunk-list');
var trunk=d.trunk||[];
if(trunk.length){
  var gr={};var order=[];
  trunk.forEach(function(it){
    var c=it.category||'Miscellany';
    if(!gr[c]){gr[c]=[];order.push(c)}
    gr[c].push(it);
  });
  var h='';
  order.forEach(function(cat){
    h+='<div class="cat-block"><div class="cat-lbl">🏷️ '+esc(cat)+'</div>';
    gr[cat].forEach(function(it){
      h+='<div class="item-row"><div class="item-top">'+
        '<span class="item-nm">'+esc(it.name||'—')+'</span>'+
        '<span class="item-dots"></span>'+
        '<span class="item-qty">×'+esc(it.qty||1)+'</span>'+
      '</div>'+
      (it.desc?'<div class="item-desc">'+esc(it.desc)+'</div>':'')+
      '</div>';
    });
    h+='</div>';
  });
  trunkEl.innerHTML=h;
}else{
  trunkEl.innerHTML='<div class="empty-note">The trunk sits empty.</div>';
}

/* NAV + COLLAPSE */
document.querySelectorAll('.nav-a').forEach(function(a){
  a.addEventListener('click',function(e){
    e.stopPropagation();
    var target=g(this.getAttribute('data-jump'));
    if(target)target.scrollIntoView({behavior:'smooth',block:'start'});
  });
});
var page=g('page');
var leaves=document.querySelectorAll('.leaf');
if(page)page.addEventListener('scroll',function(){
  var best=null,bestDist=1e9;
  leaves.forEach(function(l){
    var dd=Math.abs(l.getBoundingClientRect().top-page.getBoundingClientRect().top-4);
    if(dd<bestDist){bestDist=dd;best=l}
  });
  if(best)document.querySelectorAll('.nav-a').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-jump')===best.id)});
});

var mast=g('mast');
if(mast)mast.addEventListener('click',function(){g('stwin').classList.toggle('closed')});
})();
</script>
